export class JsonRpcStdioClient implements BridgeToolProvider {
  private child: ChildProcessWithoutNullStreams | null = null;
  private nextId = 1;
  private pending = new Map<
    number | string,
    { resolve: (v: unknown) => void; reject: (e: Error) => void; timer: NodeJS.Timeout }
  >();
  private buffer = "";
  private closed = false;

  constructor(
    readonly scriptPath: string,
    readonly scriptArgs: string[] = [],
    readonly pythonBin = process.env.MUSE_BRIDGE_PYTHON ?? "python3",
  ) {}

  get running(): boolean {
    return this.child !== null && !this.closed;
  }

  start(): void {
    if (this.child) return;
    const abs = path.isAbsolute(this.scriptPath)
      ? this.scriptPath
      : path.resolve(process.cwd(), this.scriptPath);
    if (!fs.existsSync(abs)) {
      throw new Error(`bridge script not found: ${this.scriptPath}`);
    }
    this.child = spawn(this.pythonBin, [abs, ...this.scriptArgs], {
      stdio: ["pipe", "pipe", "pipe"],
      cwd: process.cwd(),
    });
    this.closed = false;
    this.child.stdout.setEncoding("utf-8");
    this.child.stdout.on("data", (chunk) => this.onData(String(chunk)));
    this.child.stderr.setEncoding("utf-8");
    this.child.stderr.on("data", () => {
      /* Python logs stay on stderr; ignore here (callers may tap) */
    });
    this.child.on("close", (code) => {
      this.closed = true;
      for (const [, p] of this.pending) {
        clearTimeout(p.timer);
        p.reject(new Error(`bridge exited (code ${code})`));
      }
      this.pending.clear();
    });
    this.child.on("error", (err) => {
      for (const [, p] of this.pending) {
        clearTimeout(p.timer);
        p.reject(err);
      }
      this.pending.clear();
    });
  }

  private onData(chunk: string): void {
    this.buffer += chunk;
    let nl: number;
    while ((nl = this.buffer.indexOf("\n")) !== -1) {
      const line = this.buffer.slice(0, nl).trim();
      this.buffer = this.buffer.slice(nl + 1);
      if (!line) continue;
      let msg: JsonRpcResponse;
      try {
        msg = JSON.parse(line) as JsonRpcResponse;
      } catch {
        continue;
      }
      // Response to a pending request.
      if (msg.id !== undefined && msg.id !== null && (msg.result !== undefined || msg.error)) {
        const p = this.pending.get(msg.id);
        if (!p) continue;
        this.pending.delete(msg.id);
        clearTimeout(p.timer);
        if (msg.error) {
          p.reject(new Error(`bridge error ${msg.error.code}: ${msg.error.message}`));
        } else {
          p.resolve(msg.result);
        }
        continue;
      }
      // Server notification / request — no-op (MCP servers rarely call back).
    }
  }

  request(method: string, params?: unknown, timeoutMs = 30_000): Promise<unknown> {
    if (!this.child || this.closed) {
      throw new Error("bridge is not running");
    }
    const id = this.nextId++;
    const req: JsonRpcRequest = { jsonrpc: "2.0", id, method, ...(params !== undefined ? { params } : {}) };
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(new Error(`bridge request timed out: ${method}`));
      }, timeoutMs);
      this.pending.set(id, { resolve, reject, timer });
      try {
        this.child!.stdin.write(JSON.stringify(req) + "\n");
      } catch (err) {
        this.pending.delete(id);
        clearTimeout(timer);
        reject(err as Error);
      }
    });
  }

  notify(method: string, params?: unknown): void {
    if (!this.child || this.closed) return;
    this.child.stdin.write(
      JSON.stringify({ jsonrpc: "2.0", method, ...(params !== undefined ? { params } : {}) }) + "\n",
    );
  }

  async initialize(): Promise<unknown> {
    const result = await this.request("initialize", {
      protocolVersion: "2024-11-05",
      capabilities: {},
      clientInfo: { name: "muse-ts", version: "1.0.0" },
    });
    this.notify("notifications/initialized");
    return result;
  }

  async listTools(): Promise<{ name: string; description?: string; inputSchema?: unknown }[]> {
    const result = (await this.request("tools/list", {})) as {
      tools?: { name: string; description?: string; inputSchema?: unknown }[];
    };
    return Array.isArray(result.tools) ? result.tools : [];
  }

  async callTool(name: string, args: Record<string, unknown>): Promise<string> {
    const result = (await this.request("tools/call", { name, arguments: args })) as {
      content?: { type?: string; text?: string }[];
    };
    if (Array.isArray(result.content)) {
      return result.content.map((c) => c.text ?? JSON.stringify(c)).join("\n");
    }
    return JSON.stringify(result).slice(0, 20_000);
  }

  async close(): Promise<void> {
    if (!this.child) return;
    try {
      this.child.stdin.end();
    } catch {
      /* ignore */
    }
    const child = this.child;
    await new Promise<void>((resolve) => {
      const timer = setTimeout(() => {
        try {
          child.kill("SIGKILL");
        } catch {
          /* ignore */
        }
        resolve();
      }, 3000);
      child.on("close", () => {
        clearTimeout(timer);
        resolve();
      });
    });
    this.child = null;
    this.closed = true;
  }
}
